def metric(model,h,split='test',col='MAE'):return float(m[(m.model==model)&(m.horizon==h)&(m.split==split)][col].iloc[0])
def gain(h):return 100*(1-metric(sel[str(h)],h)/metric('prophet',h))
def gain_text(h):return ('снижение' if gain(h)>=0 else 'увеличение')+' ошибки относительно Prophet '+fmt(abs(gain(h)))+'%'
def fmt(x,n=1):return f'{x:,.{n}f}'.replace(',',' ').replace('.',',')

